class Solution {
    public int sumSubarrayMins(int[] arr) {
        return optimal(arr);
    }
    private int optimal(int[] arr){
        int n=arr.length;
        int mod=(int)Math.pow(10,9)+7;
        int nsei[]=new int[n];
        int psei[]=new int[n];
        Stack<Integer>stk=new Stack<>();
        for(int i=n-1;i>=0;i--){
            while(!stk.isEmpty() && arr[stk.peek()]>=arr[i]){
                stk.pop();
            }
            nsei[i]=stk.isEmpty()?n:stk.peek();
            stk.push(i);
        }
        stk.clear();
        for(int i=0;i<n;i++){
            while(!stk.isEmpty() && arr[stk.peek()]>arr[i]){
                stk.pop();
            }
            psei[i]=stk.isEmpty()?-1:stk.peek();
            stk.push(i);
        }
        int ans=0;
        for(int i=0;i<n;i++){
            ans=(ans+arr[i]*(i-psei[i])*(nsei[i]-i))%mod;
        }

        return ans;

    }
    private int bruteForce(int[] arr){
        int sum=0;
        int mod=(int)Math.pow(10,9)+7;
        for(int i=0;i<arr.length;i++){
            int min=Integer.MAX_VALUE;
            for(int j=i;j<arr.length;j++){
                min=Math.min(min,arr[j]);
                sum=(sum+min)%mod;
            }
        }
        return sum;
    }
}

