import java.util.*;

class Solution {
    public int sumSubarrayMins(int[] arr) {
        int n = arr.length;
        int mod = (int)1e9 + 7;


        int[] left = new int[n];
        int[] right = new int[n];

        Stack<Integer> st = new Stack<>();


        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && arr[st.peek()] > arr[i]) {
                st.pop();
            }
            left[i] = st.isEmpty() ? i + 1 : i - st.peek();
            st.push(i);
        }

        st.clear();


        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && arr[st.peek()] >= arr[i]) {
                st.pop();
            }
            right[i] = st.isEmpty() ? n - i : st.peek() - i;
            st.push(i);
        }

        long sum = 0;
        for (int i = 0; i < n; i++) {
            long freq = (long) left[i] * right[i];
            sum = (sum + freq * arr[i]) % mod;
        }

        return (int) sum;
    }

    public static void main(String[] args) {
        Solution sol = new Solution();
        int[] arr = {3, 1, 2, 5};
        System.out.println(sol.sumSubarrayMins(arr)); // Output: 23
    }
}


## Complexity
Time Complexity
O(n) where n is the length of the input array. There are three sequential loops each running n times; within the first two loops, each index is pushed onto and popped from the stack exactly once, leading to O(n) amortized time.
Space Complexity
O(n) to store the 'left' array of size n, the 'right' array of size n, and the 'Stack' object which can store up to n elements in the worst case.
